export function extensionArgs(
	options: Pick<OpenOptions, "loadExtension" | "keepExtensions" | "headless" | "selectorDir">,
): string[] {
	const args: string[] = [];
	const dirs = [options.loadExtension, options.selectorDir].filter(Boolean) as string[];
	const joined = dirs.join(",");
	if (joined) args.push(`--load-extension=${joined}`);
	if (options.keepExtensions) return args;
	if (dirs.length) {
		// A lone Dev Selector on a windowed profile is added, not isolated:
		// only runs already isolating (loading an extension, or headless) get
		// --disable-extensions-except. A windowed run loading nothing keeps
		// the profile's extensions.
		if (options.loadExtension || options.headless)
			args.push(`--disable-extensions-except=${joined}`);
	} else if (options.headless) args.push("--disable-extensions");
	return args;
}

/**
 * Pick the Dev Selector build under `<root>/.output`: the newer of
 * chrome-mv3 / chrome-mv3-dev by manifest.json mtime. If neither build
 * exists, name the default one (chrome-mv3) so callers can report it missing.
 */
export function resolveDevSelectorDir(root: string): string {
	const candidates = ["chrome-mv3", "chrome-mv3-dev"].map((name) =>
		join(root, ".output", name),
	);
	let best: string | undefined;
	let bestMtime = -Infinity;
	for (const dir of candidates) {
		if (!existsSync(dir)) continue;
		let mtime = -Infinity;
		try {
			mtime = statSync(join(dir, "manifest.json")).mtimeMs;
		} catch {
			try {
				mtime = statSync(dir).mtimeMs;
			} catch {}
		}
		if (mtime > bestMtime) {
			bestMtime = mtime;
			best = dir;
		}
	}
	return best ?? candidates[0];
}

